use super::*;
#[test]
fn actual_cancel_alias_probe_and_return_report_work_without_fictional_header_copy(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};
 let(token,p)=CancelToken::admit_root(RetainedCloneGrant{maximum_items:1,..bank}).unwrap().unwrap();bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;
 let(wrong,p)=CancelToken::admit_root(RetainedCloneGrant{maximum_items:1,..bank}).unwrap().unwrap();bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;
 let witness=token.clone();let mut owner=CancelTokenRetirement::from_token(token);
 let denied=owner.close_step(Default::default());assert_eq!(denied.work,row["work"]["denied"].as_u64().unwrap());assert_eq!(denied.result.unwrap().progress(),RetainedCloneProgress::default());assert!(owner.is_original_alias_witness(&witness));
 let shared=owner.close_step(RetainedCloneGrant{maximum_items:1,..bank});assert_eq!(shared.work,row["work"]["sharedProbe"].as_u64().unwrap());assert!(matches!(shared.result,Err(CancelTokenRetirementError::Blocked(CancelTokenRetirementBlocked::SharedAlias))));assert!(owner.is_original_alias_witness(&witness));
 let wrong_turn=owner.return_alias_step(&wrong,RetainedCloneGrant{maximum_items:1,..bank});assert_eq!(wrong_turn.work,row["work"]["wrongWitness"].as_u64().unwrap());assert!(matches!(wrong_turn.result,Err(CancelTokenRetirementError::Refused(_))));assert!(owner.is_original_alias_witness(&witness));
 let returned=owner.return_alias_step(&witness,RetainedCloneGrant{maximum_items:1,..bank});assert_eq!(returned.work,row["work"]["aliasReturn"].as_u64().unwrap());let p=returned.result.unwrap().progress();assert_eq!(p.copied_bytes,row["copyBytes"].as_u64().unwrap()as usize);assert_eq!(p.released_bytes,0);bank.maximum_items-=p.copied_items;assert!(owner.terminal_is_empty());let cached=owner.close_step(Default::default());assert_eq!(cached.work,row["work"]["cached"].as_u64().unwrap());assert_eq!(cached.result.unwrap().progress(),RetainedCloneProgress::default());drop(owner);
 let(oracle,_registration)=futures_util::future::AbortHandle::new_pair();let before=witness.is_cancelled();assert_eq!(before,oracle.is_aborted());witness.cancel_now();oracle.abort();let after=witness.is_cancelled();assert_eq!(after,oracle.is_aborted());assert_eq!(serde_json::json!([before,after]),row["cancellation"]);
 for token in [witness,wrong]{let mut owner=CancelTokenRetirement::from_token(token);for _ in 0..s["maximumTurns"].as_u64().unwrap(){if owner.terminal_is_empty(){break;}let turn=owner.close_step(RetainedCloneGrant{maximum_items:1,..bank});assert_eq!(turn.work,1);let p=turn.result.unwrap().progress();assert!(p.fits(bank));assert_eq!(p.copied_bytes,0);bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;}assert!(owner.terminal_is_empty());}
}
